window.SCHOOL_LISTENING={"../assets/media/2626f1c674f2d61d19052c3e5b7ff50ca8c86275bf4483e2b6d51f7182863abc.mp3":[{"id":"PPT_2626f1c674f2d61d","audioId":"PPT_2626f1c674f2d61d","title":"Book 3 · Unit 6 · LS · AUDIO TRANSCRIPT","subtitle":"AUDIO TRANSCRIPT · source slide 243","duration":62.48,"cues":[{"start":0,"end":1.52,"text":"six .four","coverage":1},{"start":1.52,"end":3.16,"text":"Good morning.","coverage":1},{"start":3.82,"end":9.64,"text":"In today's lecture, I want to discuss an invention which has changed our lives.","coverage":1},{"start":10.4,"end":14.66,"text":"This product has made a huge difference in the way we work,","coverage":1},{"start":15.04,"end":15.54,"text":"travel,","coverage":1},{"start":15.96,"end":16.58,"text":"communicate,","coverage":1},{"start":16.94,"end":18.74,"text":"and socialize with friends.","coverage":1},{"start":19.44,"end":21.02,"text":"Can you guess what it is?","coverage":1},{"start":21.64,"end":25.06,"text":"I'm talking here about mobile phone apps.","coverage":1},{"start":25.84,"end":29.18,"text":"The word app comes from application.","coverage":1},{"start":29.82,"end":30.54,"text":"Traditionally,","coverage":1},{"start":31.4,"end":35.14,"text":"applications were used in computers to help them perform better.","coverage":1},{"start":35.72,"end":36.22,"text":"However,","coverage":1},{"start":36.68,"end":38.58,"text":"with the invention of smartphones,","coverage":1},{"start":38.98,"end":43.06,"text":"the word app is used to refer to phone applications.","coverage":1},{"start":43.88,"end":49.48,"text":"In this lecture, we'll start by discussing the very first apps and their development.","coverage":1},{"start":49.98,"end":53.88,"text":"We will then discuss how apps have changed our lives.","coverage":1},{"start":53.88,"end":55.2,"text":"Finally,","coverage":1},{"start":55.66,"end":60.52,"text":"we'll focus on some of the most popular apps used by people today.","coverage":1}],"file":"0e0e70a126851b50fd87.js","track":0,"media":"../assets/media/2626f1c674f2d61d19052c3e5b7ff50ca8c86275bf4483e2b6d51f7182863abc.mp3"}],"../assets/media/7c41bea54a17a35660542add14b0e52db33404c67a4fe487d9791f58eb46224f.mp3":[{"id":"PPT_7c41bea54a17a356","audioId":"PPT_7c41bea54a17a356","title":"Book 3 · Unit 6 · LS · PREPARATION FOR SPEAKING","subtitle":"PREPARATION FOR SPEAKING · source slide 184","duration":52.06,"cues":[{"start":0,"end":1.5,"text":"six .six","coverage":1},{"start":1.5,"end":8.1,"text":"I would like to present an invention which has made the way we organise our work easier.","coverage":1},{"start":9.18,"end":12.84,"text":"It's a simple invention and most of you have used it.","coverage":1},{"start":13.32,"end":17.94,"text":"It's a small yellow piece of paper which is known all over the world.","coverage":1},{"start":18.42,"end":19.88,"text":"It's the Post -It Note.","coverage":1},{"start":20.8,"end":25.52,"text":"A Post -It Note is a piece of paper with special glue on the back.","coverage":1},{"start":26.16,"end":30.06,"text":"Modern Post -It Notes can be any colour or shape.","coverage":1},{"start":31.1,"end":32.98,"text":"Post -It Notes are simple to use.","coverage":1},{"start":33.52,"end":37.54,"text":"You can stick them on anything and the note will stay in place.","coverage":1},{"start":38.4,"end":41.5,"text":"The notes can be easily removed from any surface.","coverage":1},{"start":42.6,"end":46.14,"text":"First I am going to talk about the history of this invention.","coverage":1},{"start":46.72,"end":50.18,"text":"Then I will explain how it has made a difference in our lives.","coverage":1}],"file":"3aac822b69a905562c18.js","track":0,"media":"../assets/media/7c41bea54a17a35660542add14b0e52db33404c67a4fe487d9791f58eb46224f.mp3"}],"../assets/media/7dcec7a89cc57252cb604ddf36251f44dee4d30c7ed149d62414037e2d905129.mp3":[{"id":"PPT_7dcec7a89cc57252","audioId":"PPT_7dcec7a89cc57252","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 61","duration":44.59,"cues":[{"start":0,"end":1.56,"text":"six .three","coverage":1},{"start":2.9,"end":11.44,"text":"one The Middle Ages were an interesting time and they were full of scientific discoveries","coverage":1},{"start":14.64,"end":27.38,"text":"two Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today and","coverage":1},{"start":28,"end":31.52,"text":"Some of these inventions are very common","coverage":1},{"start":33.58,"end":34.7,"text":"three","coverage":1},{"start":35.78,"end":42.7,"text":"Many people think gunpowder is the most important invention in history","coverage":1}],"file":"41a9e62f5233ce0c9379.js","track":0,"media":"../assets/media/7dcec7a89cc57252cb604ddf36251f44dee4d30c7ed149d62414037e2d905129.mp3"}],"../assets/media/4ef34c52618f71d8774ddb0d029ef28c999545da7ab22472c5463db1b1c90251.mp3":[{"id":"PPT_4ef34c52618f71d8","audioId":"PPT_4ef34c52618f71d8","title":"Book 3 · Unit 6 · LS · LISTENING 2","subtitle":"LISTENING 2 · source slide 106","duration":285.26,"cues":[{"start":0,"end":1.56,"text":"six .five","coverage":1},{"start":1.56,"end":6.36,"text":"I'd like to start by talking a little bit about the first apps.","coverage":1},{"start":6.98,"end":9.44,"text":"These were included with each smartphone.","coverage":1},{"start":10.12,"end":15.06,"text":"These types of apps were placed in the phones to help users access the internet,","coverage":1},{"start":15.46,"end":16.24,"text":"check emails,","coverage":1},{"start":16.64,"end":18.42,"text":"send texts, and so on.","coverage":1},{"start":19.12,"end":26.5,"text":"The first apps were designed to increase efficiency at work and allow people to access important information.","coverage":1},{"start":26.5,"end":27.74,"text":"However,","coverage":1},{"start":28.18,"end":32.48,"text":"it was the second generation of apps that really changed things.","coverage":1},{"start":33.1,"end":35.14,"text":"These were downloadable apps.","coverage":1},{"start":35.76,"end":40.72,"text":"Users simply downloaded apps from the internet and installed them on their phones.","coverage":1},{"start":41.42,"end":46.94,"text":"Since its introduction, the app market has grown far beyond anyone's expectations.","coverage":1},{"start":47.72,"end":51.6,"text":"The first app store was opened in 2008.","coverage":1},{"start":51.6,"end":53.26,"text":"By 2011,","coverage":1},{"start":53.56,"end":56.88,"text":"it was reporting over ten billion downloads,","coverage":1},{"start":57.26,"end":61.3,"text":"and people were using apps more than internet browsers on their phones.","coverage":1},{"start":61.94,"end":63.44,"text":"And by 2017,","coverage":1},{"start":63.82,"end":68.6,"text":"an estimated 180 billion apps had been downloaded.","coverage":1},{"start":69.12,"end":71.82,"text":"These numbers have been growing ever since,","coverage":1},{"start":72.14,"end":78.2,"text":"and they give us a good idea about how popular apps are and how quickly they've developed.","coverage":1},{"start":78.2,"end":85.04,"text":"People from all over the world use apps for entertainment, travel, and communication.","coverage":1},{"start":85.7,"end":91.36,"text":"So I'm going to briefly talk about how these apps have changed our lives.","coverage":1},{"start":92.18,"end":96.8,"text":"It's hard to imagine life before smartphones and mobile phone apps,","coverage":1},{"start":97.24,"end":103.98,"text":"or for those of us who are old enough to remember it, but let's go ahead and make an attempt anyway.","coverage":1},{"start":103.98,"end":109.99,"text":"So imagine for a moment that you're taking a road trip in the days before smartphones.","coverage":1},{"start":111.3,"end":112.52,"text":"Weeks before the trip,","coverage":1},{"start":112.86,"end":118.54,"text":"you go to the bookstore or library to get some guidebooks about the places you're going to visit.","coverage":1},{"start":119.24,"end":121.08,"text":"A few days before you leave,","coverage":1},{"start":121.5,"end":125.38,"text":"you get some audiobooks to entertain you during the long trip.","coverage":1},{"start":126.02,"end":128.54,"text":"You go to a shop and buy some maps.","coverage":1},{"start":129.2,"end":129.7,"text":"Yes,","coverage":1},{"start":130.1,"end":131.2,"text":"the paper kind.","coverage":1},{"start":131.2,"end":139.06,"text":"The day before the trip, you sit down at your computer and look up the directions and print them out.","coverage":1},{"start":139.62,"end":143.46,"text":"Then you pack some of your favorite CDs to bring along.","coverage":1},{"start":144.02,"end":148.82,"text":"You also pack your camera and your torch in case your car breaks down.","coverage":1},{"start":149.24,"end":156.84,"text":"And you write down some phone numbers and addresses of the friends you'll be visiting and the hotels where you'll be staying.","coverage":1},{"start":157.82,"end":159.22,"text":"While you're driving,","coverage":1},{"start":159.54,"end":163.74,"text":"your passenger reads the directions to you and looks for street signs.","coverage":1},{"start":164.36,"end":169.04,"text":"If you get lost, you stop at a petrol station to ask for directions.","coverage":1},{"start":169.52,"end":172.22,"text":"You have to write them down on a piece of paper.","coverage":1},{"start":173.02,"end":173.62,"text":"Okay,","coverage":1},{"start":174,"end":176.44,"text":"so I think you get the idea.","coverage":1},{"start":177.32,"end":180.84,"text":"Now, let's make a comparison with the same trip today.","coverage":1},{"start":180.84,"end":181.3,"text":"No","coverage":1},{"start":181.3,"end":182.22,"text":"books,","coverage":1},{"start":182.8,"end":182.91,"text":"no","coverage":1},{"start":182.91,"end":183.56,"text":"maps,","coverage":1},{"start":183.94,"end":184.07,"text":"no","coverage":1},{"start":184.07,"end":184.84,"text":"CDs,","coverage":1},{"start":185.34,"end":185.46,"text":"no","coverage":1},{"start":185.46,"end":186.88,"text":"lists of phone numbers,","coverage":1},{"start":187.18,"end":187.31,"text":"no","coverage":1},{"start":187.31,"end":189.02,"text":"friend giving you directions.","coverage":1},{"start":189.58,"end":191.7,"text":"The smartphone does it all.","coverage":1},{"start":192.54,"end":195.92,"text":"Think of the apps you'd use just for that one trip.","coverage":1},{"start":196.4,"end":199.92,"text":"You'd read reviews and book your hotel with a travel app.","coverage":1},{"start":200.38,"end":205.6,"text":"The GPS would replace the directions and maps and your friend in the front seat.","coverage":1},{"start":205.6,"end":213.74,"text":"Of course, a music app would replace the CDs and you could listen to podcasts as well as audiobooks.","coverage":1},{"start":213.84,"end":217.96,"text":"And of course, you wouldn't need to bring a camera or a torch.","coverage":1},{"start":218.66,"end":223.98,"text":"Yes, we've certainly made a lot of progress since the pre -smartphone days.","coverage":1},{"start":224.84,"end":225.22,"text":"So,","coverage":1},{"start":225.6,"end":229.84,"text":"now I'd like to mention another important effect of the invention of apps.","coverage":1},{"start":230.6,"end":234.32,"text":"It has created a whole new IT sector.","coverage":1},{"start":234.32,"end":240.6,"text":"It is one of the fastest growing industries and there is a great need for skilled software engineers.","coverage":1},{"start":241.64,"end":244.28,"text":"But apps have also had some negative effects.","coverage":1},{"start":244.88,"end":251.06,"text":"For one thing, people have become more helpless because they're so dependent on their phones for information.","coverage":1},{"start":251.84,"end":254.06,"text":"For example, if they're in a place with","coverage":1},{"start":254.06,"end":254.42,"text":"no","coverage":1},{"start":254.42,"end":259.48,"text":"phone signal, they're not very good at asking for and following directions.","coverage":1},{"start":259.48,"end":265.18,"text":"And apps have made people less patient because they expect to have information immediately.","coverage":1},{"start":266.28,"end":266.86,"text":"In fact,","coverage":1},{"start":267.16,"end":275.6,"text":"a recent study found that 87 % of smartphone users leave a web page if it doesn't load in two seconds.","coverage":1},{"start":276.72,"end":277.18,"text":"Okay,","coverage":1},{"start":277.62,"end":279.18,"text":"in the next part of the lecture,","coverage":1},{"start":279.62,"end":283.38,"text":"I'll discuss some of the most common apps in more details.","coverage":1}],"file":"af907f48532db4c9fb5c.js","track":0,"media":"../assets/media/4ef34c52618f71d8774ddb0d029ef28c999545da7ab22472c5463db1b1c90251.mp3"}],"../assets/media/794f23af8c052c3c25b881a9068d4d602ab67d68dabdcd866f29b77ae38110cb.mp3":[{"id":"PPT_794f23af8c052c3c","audioId":"PPT_794f23af8c052c3c","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 58","duration":47.36,"cues":[{"start":0,"end":1.8,"text":"six .two","coverage":1},{"start":2.84,"end":7.3,"text":"one Inventions and technology from India,","coverage":1},{"start":7.72,"end":8.22,"text":"China,","coverage":1},{"start":8.88,"end":13.04,"text":"North Africa and the Middle East were brought to Europe.","coverage":1},{"start":15.1,"end":16.1,"text":"two","coverage":1},{"start":16.92,"end":23.08,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1},{"start":25.42,"end":26.42,"text":"three","coverage":1},{"start":27.38,"end":34.66,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":1},{"start":36.98,"end":37.52,"text":"four","coverage":1},{"start":38.54,"end":40.04,"text":"As we move along,","coverage":1},{"start":40.42,"end":45.4,"text":"you'll find one of the most important inventions of medieval times.","coverage":1}],"file":"bdff2ed6f667e54b9584.js","track":0,"media":"../assets/media/794f23af8c052c3c25b881a9068d4d602ab67d68dabdcd866f29b77ae38110cb.mp3"}],"../assets/media/29189f22a5fca65b8fe5d20d22fb2a4cb498020520091f4cd316451425ae7259.mp3":[{"id":"PPT_29189f22a5fca65b","audioId":"PPT_29189f22a5fca65b","title":"Book 3 · Unit 6 · LS · LISTENING 1","subtitle":"LISTENING 1 · source slide 48","duration":291.37,"cues":[{"start":0,"end":1.3,"text":"Unit six,","coverage":1},{"start":1.72,"end":3.4,"text":"six .one","coverage":1},{"start":3.4,"end":6.68,"text":"Welcome to the Museum of Science.","coverage":1},{"start":7.36,"end":13.42,"text":"The exhibition that we're about to see is called Discovering Medieval Science.","coverage":1},{"start":14.14,"end":20.06,"text":"As some of you may know, the Middle Ages have often been called the Dark Ages.","coverage":1},{"start":20.92,"end":22.26,"text":"During this tour,","coverage":1},{"start":22.62,"end":25.56,"text":"you will find out that they were not.","coverage":1},{"start":25.56,"end":33.52,"text":"The Middle Ages were an interesting time and they were full of scientific discoveries.","coverage":1},{"start":34.92,"end":36.02,"text":"During this time,","coverage":1},{"start":36.68,"end":39.52,"text":"inventions and technology from India,","coverage":1},{"start":40.04,"end":40.56,"text":"China,","coverage":1},{"start":41.32,"end":45.62,"text":"North Africa and the Middle East were brought to Europe.","coverage":1},{"start":46.94,"end":58.02,"text":"Inventions and machines designed by medieval scholars made a great contribution to society and many are still in use today.","coverage":1},{"start":58.8,"end":62.42,"text":"And some of these inventions are very common.","coverage":1},{"start":63.22,"end":70.6,"text":"For example, the first fountain pen was made in 953 in Africa.","coverage":1},{"start":71.66,"end":76.86,"text":"Before then, people used bird feathers and ink to write with.","coverage":1},{"start":77.8,"end":83.78,"text":"This method would often leave your fingers and clothes covered with black ink.","coverage":1},{"start":83.78,"end":97.14,"text":"So the first fountain pen had a small container with ink inside and did not stain people's clothes or fingers while the user was writing.","coverage":1},{"start":98.46,"end":103.8,"text":"You can see a model of this fountain pen in room 11b.","coverage":1},{"start":104.16,"end":108.5,"text":"In the same room, you'll find early examples of glasses.","coverage":1},{"start":108.5,"end":113.8,"text":"Glasses were invented in Italy in the 13th century.","coverage":1},{"start":114.62,"end":114.71,"text":"No","coverage":1},{"start":114.71,"end":117.04,"text":"one knows who invented them.","coverage":1},{"start":117.58,"end":123.26,"text":"The first glasses were held in front of the eyes or balanced on the nose.","coverage":1},{"start":124.3,"end":128.28,"text":"They were developed to help people with bad vision to read.","coverage":1},{"start":129.26,"end":133.18,"text":"But let's now move on to some other inventions.","coverage":1},{"start":134.06,"end":137.5,"text":"In rooms 12a and 12b,","coverage":1},{"start":137.84,"end":143,"text":"we have works by the great medieval engineer Al -Jazari.","coverage":1},{"start":143.98,"end":147.66,"text":"Al -Jazari lived in 12th century Turkey.","coverage":1},{"start":148.42,"end":162.48,"text":"His work, The Book of Knowledge of Ingenious Mechanical Devices, lists 100 different machines with instructions and diagrams explaining how to build them.","coverage":1},{"start":163.54,"end":164.48,"text":"In this exhibition,","coverage":1},{"start":164.88,"end":170.14,"text":"you can see models of some of the devices which were designed by Al -Jazari.","coverage":1},{"start":171.14,"end":174.36,"text":"Here you can see his mechanical clocks.","coverage":1},{"start":175.5,"end":179.28,"text":"Water and weights make the clocks work.","coverage":1},{"start":179.28,"end":184.78,"text":"However, his most important invention was the crankshaft.","coverage":1},{"start":185.74,"end":192.1,"text":"The crankshaft is a long arm which allows machines to move in a straight line.","coverage":1},{"start":193.02,"end":198.12,"text":"It was first used for watering gardens and fields on farms.","coverage":1},{"start":199.12,"end":200.56,"text":"In more modern times,","coverage":1},{"start":200.92,"end":203.94,"text":"a crankshaft is used in car engines.","coverage":1},{"start":205.02,"end":211.48,"text":"As we move along, you'll find one of the most important inventions of medieval times.","coverage":1},{"start":212.42,"end":219.1,"text":"This invention has changed the history of the world in ways that we can't even imagine.","coverage":1},{"start":220.18,"end":224.44,"text":"It's one of the four great inventions of Chinese culture,","coverage":1},{"start":225.24,"end":226.38,"text":"gunpowder.","coverage":1},{"start":226.38,"end":238.28,"text":"Gunpowder was invented in the 9th century by Chinese scientists who were trying to create a powder which would make you live forever.","coverage":1},{"start":239.36,"end":242.16,"text":"They weren't successful, of course,","coverage":1},{"start":242.5,"end":247.88,"text":"but their attempts led to the invention of fireworks and weapons.","coverage":1},{"start":248.82,"end":257.84,"text":"The first instructions on how to make gunpowder were written in the 11th century by Zeng Gongliang,","coverage":1},{"start":258.22,"end":260.84,"text":"Ding Du and Yang Wei De.","coverage":1},{"start":262.04,"end":266.96,"text":"The invention of gunpowder has changed the way we fight wars.","coverage":1},{"start":267.9,"end":275.22,"text":"It changed the outcome of many medieval battles and affected the history of the world.","coverage":1},{"start":275.22,"end":282.68,"text":"Many people think gunpowder is the most important invention in history.","coverage":1},{"start":284.28,"end":289.4,"text":"Now, let's move to the next room, which is all about medieval medicine.","coverage":1}],"file":"defa4479b8b5e4663a14.js","track":0,"media":"../assets/media/29189f22a5fca65b8fe5d20d22fb2a4cb498020520091f4cd316451425ae7259.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1 Work with a partner and answer the questions. What are the four “STEM” subjects? a Science, Technology, Engineering, Mechanics b Science, Technology, Engineering, Maths c Science, Technology, Economics, Mathsb — Science, Technology, Engineering, Maths.","slide":4,"shape":"19","bookPage":"126"},{"text":"1 Can you think of any famous people who work in a STEM industry? How did they become famous?James Dyson is known for developing a vacuum cleaner that worked differently from other models.","slide":4,"shape":"20","bookPage":"126"},{"text":"1 What do you think makes somebody a good research scientist? What interests and abilities do they have?A good researcher may be curious, think critically, test ideas carefully and work well with others.","slide":5,"shape":"19","bookPage":"126"},{"text":"1 What is happening in each photo? Which job do you find most interesting? Why?Possible answer:The photos show work with electronic equipment, water research, an eye examination and a medical team performing an operation. I find water research interesting because it takes place outdoors.","slide":7,"shape":"28","bookPage":"126"},{"text":"2 What do you think the main topic(s) of the video will be?Possible answer:The video may explain what scientists do and which skills their work requires.","slide":7,"shape":"29","bookPage":"126"},{"text":"3 In the video you will hear about three inventions. What do you think these might be?Possible answer:Possible inventions: an electronic device, equipment for studying water, and a treatment for eye problems.","slide":7,"shape":"30","bookPage":"126"},{"text":"1  Testing ideas is fundamental to science.","slide":15,"shape":"8","bookPage":"126"},{"text":"2  The body’s immune system protects it against infection.","slide":15,"shape":"9","bookPage":"126"},{"text":"3  A cataract affects the eye and makes it hard to see.","slide":15,"shape":"10","bookPage":"126"},{"text":"4  The team developed a vaccine to prevent a disease.","slide":15,"shape":"11","bookPage":"126"},{"text":"5  A pandemic infects many people at the same time.","slide":15,"shape":"12","bookPage":"126"},{"text":"6  The doctor explained the treatment for the illness.","slide":15,"shape":"13","bookPage":"126"},{"text":"Research scientists have a range of skills. They enjoy testing their ideas and assessing (1) solutions — a fundamental part of science.","slide":18,"shape":"17","bookPage":"127"},{"text":"They also possess (2) mental flexibility and know that there is rarely a single (3) solution.","slide":18,"shape":"18","bookPage":"127"},{"text":"They should be able to accept changes in their working life, because their job can take them to a range of (4) environments.","slide":19,"shape":"20","bookPage":"127"},{"text":"A research scientist often works in this industry because they want to make a difference to the (5) lives of others.","slide":19,"shape":"21","bookPage":"127"},{"text":"Which type of thinking does the speaker say is “fundamental to science”? a critical b logical c practical a — critical.","slide":23,"shape":"16","bookPage":"127"},{"text":"What did James Dyson use during his first attempt at creating a vacuum cleaner? a cardboard b plastic wire c sticky tape a and c — cardboard and sticky tape.","slide":23,"shape":"17","bookPage":"127"},{"text":"In which location(s) might a research scientist work? a underwater b in space c in a lecture hall a, b and c — underwater, in space and in a lecture hall.","slide":24,"shape":"16","bookPage":"127"},{"text":"Which area did the creators of BioNTech first want to research? a Covid-19 b cancer c the immune system b — cancer.","slide":24,"shape":"17","bookPage":"127"},{"text":"5 Discuss the questions below in a small group. Which of the people mentioned in the video has had the most positive effect on the world? Why?I would choose Patricia Bath because her invention helps remove cataracts and is used in many countries.","slide":26,"shape":"16","bookPage":"127"},{"text":"5 Based on the video, what effects has the work of research scientists had on your life?Research has affected the devices I use and the treatments available to people around me.","slide":26,"shape":"17","bookPage":"127"},{"text":"1 Work in groups. Look at the photos and discuss the questions. Which of these inventions do you think is the oldest?I think paper money may be the oldest.","slide":29,"shape":"20","bookPage":"128"},{"text":"1 Which do you think is the newest?I think the mechanical clock may be the newest.","slide":29,"shape":"21","bookPage":"128"},{"text":"1 Which do you think has been the most useful?I would choose paper money because it makes it easier to exchange goods without carrying heavy objects.","slide":29,"shape":"22","bookPage":"128"},{"text":"1 Where in the world do you think they were invented? Why do you think this?I think paper money may have originated in China. I am less certain about the other two.","slide":30,"shape":"20","bookPage":"128"},{"text":"In the twelfth century, al-Jazari drew diagrams and gave detailed descriptions of machines for farming.","slide":41,"shape":"15","bookPage":"128"},{"text":"Certain people who have made a huge contribution to science and the arts receive an award called the Nobel Prize.","slide":41,"shape":"16","bookPage":"128"},{"text":"Iron is a material that people first used to make weapons in the twelfth century BCE.","slide":42,"shape":"18","bookPage":"128"},{"text":"The discovery of electricity in the eighteenth century changed the organization of human society.","slide":42,"shape":"19","bookPage":"128"},{"text":"A baby monitor is a device which lets parents watch their child when they’re in a different room.","slide":43,"shape":"17","bookPage":"128"},{"text":"Although we believe our company’s new invention will be very popular with customers, it is too early to predict the outcome.","slide":43,"shape":"18","bookPage":"128"},{"text":"There are many important scholars at universities today whose work will have a huge effect on the world as we know it.","slide":43,"shape":"19","bookPage":"128"},{"text":"Modern technology, such as computers and mobile phones, has completely changed our lives over the past 50 years.","slide":43,"shape":"5","bookPage":"128"},{"text":"1  the fountain pen  d","slide":46,"shape":"6","bookPage":"129"},{"text":"2  glasses  c","slide":46,"shape":"7","bookPage":"129"},{"text":"3  gunpowder  a","slide":46,"shape":"8","bookPage":"129"},{"text":"4  the crankshaft  b","slide":46,"shape":"9","bookPage":"129"},{"text":"a 3 A problem that fountain pens solved.","slide":49,"shape":"19","bookPage":"129"},{"text":"b 4 How and when glasses were invented.","slide":49,"shape":"20","bookPage":"129"},{"text":"c 5 The inventions of a great engineer.","slide":49,"shape":"21","bookPage":"129"},{"text":"d 2 Where these inventions were brought from and to.","slide":50,"shape":"19","bookPage":"129"},{"text":"f 6 Why the Middle Ages were important in the development of science.","slide":50,"shape":"21","bookPage":"129"},{"text":"Topic\nNotes\nFountain pen\nInvented in the year 953 in Africa. People previously wrote with bird feathers and they used to get ink on their fingers and clothes. First fountain pen used a small container to avoid this problem.\nGlasses\nInvented in Italy in the thirteenth century. People held them in front of their eyes or rested them on their noses.","slide":55,"shape":"14","bookPage":"129"},{"text":"Topic\nNotes\nAl-Jazari\nA famous engineer from the Middle Ages; lived in Türkiye in the twelfth century.\nExamples of inventions\nA mechanical clock that needed water and weights to work. The crankshaft — a device that keeps machines going in a straight line (used today in car engines).","slide":56,"shape":"15","bookPage":"130"},{"text":"Topic\nNotes\nOrigin\nInvented in China in the ninth century. The inventors were searching for a way that would allow people to live forever.\nInstructions and effects\nFirst instructions for making gunpowder came in the eleventh century. Gunpowder had a big effect on the methods and outcomes of wars and battles.","slide":57,"shape":"14","bookPage":"130"},{"text":"Inventions and technology from India, China, North Africa, and the Middle East were brought to Europe.","slide":59,"shape":"6","bookPage":"131"},{"text":"The first glasses were held in front of the eyes or balanced on the nose.","slide":59,"shape":"9","bookPage":"131"},{"text":"The crankshaft is a long arm which allows machines to move in a straight line.","slide":60,"shape":"6","bookPage":"131"},{"text":"As we move along, you’ll find one of the most important inventions of medieval times.","slide":60,"shape":"9","bookPage":"131"},{"text":"1  The Middle Ages were an interesting time and they WERE full of scientific discoveries.\nb","slide":63,"shape":"6","bookPage":"131"},{"text":"2  Inventions and machines designed by medieval scholars made a great contribution to\nsociety and many are still in use today. AND some of these inventions are very common.\nc","slide":63,"shape":"7","bookPage":"131"},{"text":"3  Many people think gunpowder is THE most important invention in history. a","slide":63,"shape":"8","bookPage":"131"},{"text":"11. What idea does the exhibition challenge?\nA. That medieval inventions influenced later everyday life.\nB. That scientific ideas travelled between different regions.\nC. That the Middle Ages lacked important scientific progress.","slide":66,"shape":"5","bookPage":null},{"text":"12. What practical problem did the fountain pen address?\nA. Difficulty reading very small handwritten letters.\nB. A shortage of materials for making paper.\nC. Ink getting onto the writer’s hands and clothing.","slide":67,"shape":"5","bookPage":null},{"text":"1 Read the introduction to a lecture about an invention. Can you guess the name of the invention?Mobile phone apps / applications.","slide":73,"shape":"21","bookPage":"136"},{"text":"1 What two words are used to refer to it?app and application.","slide":73,"shape":"22","bookPage":"136"},{"text":"7  Smartphones allow us to stay in touch with each other.","slide":86,"shape":"11","bookPage":"136"},{"text":"4 Discuss the questions below in a small group. How have smartphones and tablets changed our lives?They let us communicate, find directions and look up information while away from home.","slide":88,"shape":"16","bookPage":"137"},{"text":"4 What would your everyday life be like without your smartphone?I would use printed maps and arrange meeting times in advance. I might be less distracted, but some tasks would take longer.","slide":88,"shape":"17","bookPage":"137"},{"text":"5 Work with a partner. Read the text and answer the questions. How can you find information about the place that you want to visit?Get guidebooks from a bookstore or library.","slide":91,"shape":"17","bookPage":"137"},{"text":"5 Which forms of entertainment could you use in the car while you drive?Listen to audio books or favourite CDs.","slide":91,"shape":"18","bookPage":"137"},{"text":"5 How will you find your way to your destination? What will you do if you get lost?Buy paper maps, print directions, ask a passenger to read them, and ask at a petrol station if lost.","slide":92,"shape":"17","bookPage":"137"},{"text":"5 Where are the address and phone numbers of the hotels where you want to stay?Write down phone numbers and addresses before leaving.","slide":92,"shape":"18","bookPage":"137"},{"text":"7 Read Text A and underline key information. “I’d like to start by talking a little bit about the first apps. These were included with each smartphone. These types of apps were placed on the phones to help users access the internet, check emails, send texts and so on. The first apps were designed to increase efficiency at work and allow people to access important information. However, it was the second generation of apps that really changed things. These were downloadable apps. Users simply downloaded apps from the internet and installed them on their phones. Since its introduction, the app market has grown far beyond anyone’s expectations.”","slide":101,"shape":"19","bookPage":"137"},{"text":"7 Read Text B and underline key information. “The first app store was opened in 2008. By 2011, it was reporting over 10 billion downloads and people were using apps more than internet browsers on their phones. And by 2017, an estimated 180 billion apps had been downloaded. These numbers have been growing ever since and they give us a good idea about how popular apps are and how quickly they’ve developed. People from all over the world use apps for entertainment, travel and communication.”","slide":102,"shape":"19","bookPage":"137"},{"text":"7 Read Text C and underline key information. “It has created a whole new IT sector. It is one of the fastest-growing industries and there is a great need for skilled software engineers. But apps have also had some negative effects. For one thing, people have become more helpless because they’re so dependent on their phones for information. And apps have made people less patient because they expect to have information immediately. In fact, a recent study found that 87 percent of smartphone users leave a web page if it doesn’t load in two seconds.”","slide":103,"shape":"19","bookPage":"137"},{"text":"The first apps helped people access the internet, check emails and send texts. The first app store opened in 2008. By 2011 there had been 10 billion downloads, and by 2017 there had been 180 billion downloads.","slide":108,"shape":"17","bookPage":"138"},{"text":"The app industry needs skilled software engineers. However, people have become more helpless because they depend on their phones, and less patient because they expect immediate information.","slide":109,"shape":"20","bookPage":"138"},{"text":"First apps\nused for\nSecond generation apps\nAnother effect\nNegative effects\naccessing the internetcheck emailssend texts\nfirst app store opened in 2008by 2011, 10 billion downloads — people used apps more than internet browsersby 2017, 180 billion downloads\nthere is a need for skilled software engineers\npeople are more helplesspeople are less patient","slide":110,"shape":"12","bookPage":"137"},{"text":"1 We’ll start by discussing the very first apps and their development.","slide":112,"shape":"17","bookPage":"138"},{"text":"2 We will then discuss how apps have changed our lives.","slide":112,"shape":"18","bookPage":"138"},{"text":"3 I’d like to start by talking a little bit about the first apps.","slide":112,"shape":"19","bookPage":"138"},{"text":"4 I’m going to briefly talk about how these apps have changed our lives.","slide":113,"shape":"17","bookPage":"138"},{"text":"5 Now I’d like to mention another important effect of the invention of apps.","slide":113,"shape":"18","bookPage":"138"},{"text":"6 In the next part of the lecture, I’ll discuss some of the most common apps in more detail.","slide":113,"shape":"19","bookPage":"138"},{"text":"2  My professor made me rewrite my assignment because there were too many\nmistakes.  F","slide":116,"shape":"7","bookPage":"132"},{"text":"3  Social media makes it easy for people to stay in touch.  C","slide":116,"shape":"8","bookPage":"132"},{"text":"4  The new discovery made a lot of people very happy.  C","slide":116,"shape":"9","bookPage":"132"},{"text":"5  I made myself stay up late to finish the work.  F","slide":116,"shape":"10","bookPage":"132"},{"text":"attempt — make","slide":126,"shape":"17","bookPage":"133"},{"text":"comparison — make","slide":126,"shape":"18","bookPage":"133"},{"text":"contribution — make","slide":126,"shape":"19","bookPage":"133"},{"text":"decision — make","slide":126,"shape":"5","bookPage":"133"},{"text":"difference — make","slide":126,"shape":"6","bookPage":"133"},{"text":"experiment — do","slide":126,"shape":"7","bookPage":"133"},{"text":"improvement — make","slide":127,"shape":"17","bookPage":"133"},{"text":"investment — make","slide":127,"shape":"18","bookPage":"133"},{"text":"public — make public","slide":127,"shape":"19","bookPage":"133"},{"text":"research — do","slide":127,"shape":"5","bookPage":"133"},{"text":"If you make a comparison between these two TVs, you’ll see that this one has a much clearer picture.","slide":131,"shape":"15","bookPage":"133"},{"text":"I like both of these bikes a lot. I’m finding it hard to make a decision about which one to buy.","slide":131,"shape":"16","bookPage":"133"},{"text":"Medieval scholars made a contribution to the world by inventing things that allowed societies to grow and become wealthier.","slide":132,"shape":"18","bookPage":"133"},{"text":"Inventors have made attempts on many occasions to build flying cars, and they are getting closer to something drivers can buy.","slide":132,"shape":"19","bookPage":"133"},{"text":"Ten years ago, Andrew made an investment in a new technology company. He’s now a millionaire.","slide":133,"shape":"17","bookPage":"133"},{"text":"The invention of the light bulb made a difference to people’s lifestyles. After it was invented, people could work indoors for longer, even when it was dark.","slide":133,"shape":"18","bookPage":"133"},{"text":"This is a good smartphone, but they could still make improvements to it, like longer battery life.","slide":133,"shape":"19","bookPage":"133"},{"text":"The government won’t make public who the people are until the police confirm the details.","slide":133,"shape":"5","bookPage":"133"},{"text":"h  to create, give or do something to create more success for something else  — 3. Sentence 3 uses made a contribution to express this meaning.","slide":137,"shape":"6","bookPage":"133"},{"text":"e  to change or add to something to make it better  — 7. Sentence 7 uses make improvements to express this meaning.","slide":137,"shape":"10","bookPage":"133"},{"text":"f  to put money into something to make more money  — 5. Sentence 5 uses made an investment to express this meaning.","slide":137,"shape":"11","bookPage":"133"},{"text":"g  to share information about something to a wider group of people  — 8. Sentence 8 uses make public to express this meaning.","slide":137,"shape":"12","bookPage":"133"},{"text":"How do you make a decision when you have two good options?","slide":140,"shape":"16","bookPage":"133"},{"text":"What improvements would you like to make to your classroom?","slide":140,"shape":"17","bookPage":"133"},{"text":"1 The Middle Ages were an interesting time, and they were full of scientific discoveries. During this time, inventions and technology from India, China, North Africa and the Middle East were brought to Europe.","slide":146,"shape":"15","bookPage":"134"},{"text":"2 And some of these inventions are very common. For example, the first fountain pen was made in 953 in Africa.","slide":146,"shape":"16","bookPage":"134"},{"text":"3 Glasses were invented in Italy in the thirteenth century. No one knows who invented them. The first glasses were held in front of the eyes or balanced on the nose. They were developed to help people with bad vision to read.","slide":146,"shape":"17","bookPage":"134"},{"text":"4 His most important invention was the crankshaft. The crankshaft is a long arm which allows machines to move in a straight line. It was first used for watering gardens.","slide":147,"shape":"19","bookPage":"134"},{"text":"1 The first smartphone, named Simon, was created by IBM.","slide":149,"shape":"15","bookPage":"135"},{"text":"2 The first newspaper was printed in 1605 in Germany.","slide":149,"shape":"16","bookPage":"135"},{"text":"3 The first computer program was written by Ada Lovelace.","slide":150,"shape":"15","bookPage":"135"},{"text":"the law of gravity – discover – Isaac Newton – the seventeenth century The law of gravity was discovered by Isaac Newton in the seventeenth century.","slide":152,"shape":"15","bookPage":"135"},{"text":"the first computer chip – invent – the 1950s The first computer chip was invented in the 1950s.","slide":152,"shape":"16","bookPage":"135"},{"text":"the first smartphone – create – after 1997 The first smartphone was created after 1997.","slide":153,"shape":"18","bookPage":"135"},{"text":"penicillin – first discover – 1928 – Alexander Fleming Penicillin was first discovered in 1928 by Alexander Fleming.","slide":153,"shape":"19","bookPage":"135"},{"text":"first email send 1971 The first email was sent in 1971.","slide":156,"shape":"16","bookPage":"135"},{"text":"telephone invent 1876 The telephone was invented in 1876.","slide":156,"shape":"17","bookPage":"135"},{"text":"Edison develop first light bulb 1879 Edison developed his first light bulb in 1879.","slide":156,"shape":"18","bookPage":"135"},{"text":"720,000 hours video share social media every day 720,000 hours of video are shared on social media every day.","slide":157,"shape":"19","bookPage":"135"},{"text":"Egyptian architect called Imhotep design pyramid of Djoser An Egyptian architect called Imhotep designed the pyramid of Djoser.","slide":157,"shape":"20","bookPage":"135"},{"text":"very early calculator create Blaise Pascal A very early calculator was created by Blaise Pascal.","slide":158,"shape":"19","bookPage":"135"},{"text":"millions people download smartphone apps every hour Millions of people download smartphone apps every hour.","slide":158,"shape":"20","bookPage":"135"},{"text":"letters write fountain pens many years now Letters have been written with fountain pens for many years now.","slide":158,"shape":"21","bookPage":"135"},{"text":"11 Work with a partner. What do you know about the inventions mentioned in Exercises 8, 9 and 10?Smartphones combine several tools in one portable device. Hearing aids help people hear better. Computer programs tell computers what to do.","slide":163,"shape":"16","bookPage":"135"},{"text":"Our pencil holder is made from an old tin. The outside is covered with paper. It keeps pencils together on a desk.","slide":167,"shape":"6","bookPage":null},{"text":"Our app could list library events. It would be created for local readers. It could make event information easier to find.","slide":168,"shape":"6","bookPage":null},{"text":"The model is made of cardboard.","slide":168,"shape":"9","bookPage":null},{"text":"11. What point does the guide illustrate when first introducing the fountain pen?\nA. The pen made writing much faster for the people who used it.\nB. The exhibition displays original medieval objects rather than models.\nC. Some medieval inventions remain familiar in everyday life.","slide":174,"shape":"5","bookPage":null},{"text":"12. Why was the fountain pen an improvement on bird feathers?\nA. It kept ink from staining the writer's fingers and clothes\nB. It allowed writers to use no ink at all\nC. It was designed to make glasses easier to hold","slide":175,"shape":"5","bookPage":null},{"text":"1. The museum tour challenges the idea that the Middle Ages lacked scientific achievement.\nAnswer: TRUE","slide":178,"shape":"5","bookPage":null},{"text":"2. The first fountain pen was invented in Italy.\nAnswer: FALSE","slide":178,"shape":"8","bookPage":null},{"text":"Our first handle was made from a narrow strip. It was tested by two classmates. They found it uncomfortable to hold. A wider strip was added to the second version.","slide":184,"shape":"6","bookPage":null},{"text":"The box originally had no labels. Picture labels were added to its drawers. They make the tools easier to find. A new user can choose the right drawer quickly.","slide":184,"shape":"9","bookPage":null},{"text":"Help people read","slide":188,"shape":"14","bookPage":"139"},{"text":"Italy","slide":188,"shape":"17","bookPage":"139"},{"text":"Thirteenth century","slide":188,"shape":"20","bookPage":"139"},{"text":"Unknown in the recording","slide":188,"shape":"23","bookPage":"139"},{"text":"Glasses","slide":188,"shape":"26","bookPage":"139"},{"text":"Held before the eyes or balanced on the nose","slide":188,"shape":"29","bookPage":"139"},{"text":"Possible answer:You could add when you last used the invention and how it helped you. The recording says nobody knows who invented glasses, so leave the inventor unnamed.","slide":190,"shape":"16","bookPage":"140"},{"text":"Possible answer:Explain what life would be like without the invention and add an example of a daily activity it supports. Say which information comes from the recording and which part is your own experience.","slide":196,"shape":"16","bookPage":"141"},{"text":"1 mentions the invention’s name in the first sentence No","slide":198,"shape":"16","bookPage":"141"},{"text":"2 gives a description of the invention Yes","slide":198,"shape":"17","bookPage":"141"},{"text":"3 says how you can use it Yes","slide":198,"shape":"18","bookPage":"141"},{"text":"4 gives specific details of how it was invented No","slide":199,"shape":"20","bookPage":"141"},{"text":"5 explains what will happen next in the presentation Yes","slide":199,"shape":"21","bookPage":"141"},{"text":"I would like to present an invention which has changed the way we organize papers. It’s the paperclip. A paperclip is a small piece of bent wire. You can use it to hold sheets of paper together. First, I am going to talk about its design. Then, I will explain how it makes organizing papers easier.","slide":202,"shape":"17","bookPage":"141"},{"text":"I would like to present an invention which has changed the way we write. It’s the ballpoint pen. A ballpoint pen is a writing tool with a small ball at its tip. You can use it to write notes. First, I am going to talk about how it works. Then, I will explain why people find it useful.","slide":202,"shape":"18","bookPage":"141"},{"text":"a  Why do people use them?  6","slide":207,"shape":"6","bookPage":"142"},{"text":"b  Who invented them?  2","slide":207,"shape":"7","bookPage":"142"},{"text":"c  Where can people use them?  5","slide":207,"shape":"8","bookPage":"142"},{"text":"d  Why were they invented?  3","slide":207,"shape":"9","bookPage":"142"},{"text":"f  What is the best thing about the invention?  7","slide":207,"shape":"11","bookPage":"142"},{"text":"g  When were they first sold?  4","slide":207,"shape":"12","bookPage":"142"},{"text":"GPS allows us to find our way around unknown places.","slide":209,"shape":"14","bookPage":"143"},{"text":"The mobile phone helps people to stay in touch.","slide":209,"shape":"15","bookPage":"143"},{"text":"Translation apps are useful for learning another language.","slide":209,"shape":"16","bookPage":"143"},{"text":"Television makes it easy to learn about the world.","slide":210,"shape":"18","bookPage":"143"},{"text":"Without the computer chip, we wouldn’t be able to use laptops.","slide":210,"shape":"19","bookPage":"143"},{"text":"Possible answer:A laptop allows us to work in different places. It is useful for writing and finding information. It makes it easy to carry our work from home to class.","slide":213,"shape":"13","bookPage":"143"},{"text":"Possible answer:A: This invention allows us to write without using a keyboard. It is useful for taking quick notes.B: Is it a ballpoint pen?A: Yes. It makes it easy to write on paper wherever we are.","slide":216,"shape":"19","bookPage":"143"},{"text":"Possible feedback: Your introduction previews the history, uses and importance of glasses. Continue in that order.","slide":226,"shape":"19","bookPage":"144"},{"text":"Possible feedback: Use ‘Glasses were invented in Italy in the thirteenth century’ and make ‘they’ refer clearly to glasses.","slide":226,"shape":"20","bookPage":"144"},{"text":"Possible feedback: Add one example of an everyday activity, such as reading a book or following a lesson.","slide":226,"shape":"21","bookPage":"144"},{"text":"Possible answer:I would like to present an invention which has changed many people’s lives: glasses. I’d like to start by talking about the early glasses described in the museum tour. Then, I’ll discuss how people use them. Finally, I’ll explain why I think they are important.","slide":229,"shape":"13","bookPage":"144"},{"text":"Possible answer:According to the museum tour, glasses were invented in Italy in the thirteenth century. The recording does not name an inventor because nobody knows who invented them. The first glasses were held in front of the eyes or balanced on the nose. They were developed to help people with poor vision read.","slide":230,"shape":"14","bookPage":"144"},{"text":"Possible answer:Glasses allow people to see more clearly. They are useful for reading, studying and carrying out everyday activities. Without them, some people would find these tasks much more difficult. This simple invention can therefore make a big difference to daily life.","slide":231,"shape":"14","bookPage":"144"},{"text":"Possible answer:I think glasses have had a strong influence because seeing clearly supports so many other activities. They can help somebody read a book, follow a lesson or recognize details around them. Although other inventions are also important, this is the one I would choose for its direct effect on everyday life.","slide":232,"shape":"13","bookPage":"144"},{"text":"I’d like to start … Then … Finally …","slide":233,"shape":"7","bookPage":"144"},{"text":"were invented; were held; were developed","slide":233,"shape":"10","bookPage":"144"},{"text":"allow people to see; useful for reading; make a big difference","slide":234,"shape":"7","bookPage":"144"},{"text":"They / them refer to glasses; this simple invention refers to the same object.","slide":234,"shape":"10","bookPage":"144"},{"text":"The history is attributed to the museum tour; the final evaluation is the speaker’s\nopinion.","slide":234,"shape":"13","bookPage":"144"},{"text":"I would like to introduce a reusable page marker. First, I will describe how it stays in place. Its folded shape grips the page. It helps readers return to an important section.","slide":238,"shape":"6","bookPage":null},{"text":"Our bag has a separate pocket near the handle. The pocket is closed with a short zip. It allows users to reach a travel card quickly. This is useful when the main section is full.","slide":238,"shape":"9","bookPage":null}];
